import * as React from 'react'

import {
  BuildTabs,
  BuildTypeTabs,
  BuildTypeTabsWithoutAliases,
  JobTabs,
  ProjectTabs,
  ProjectTabsWithoutAliases,
} from '../components/common/ToggleSakuraUI/ToggleSakuraUI.utils'
import {getTabsArg} from '../rest/tabs'
import {getBuild, getTabUrl} from '../selectors'
import {restApi} from '../services/rest'
import type {BuildId, BuildTypeId, NodeType, PipelineId, ProjectId, Tab, TabParams} from '../types'
import {
  ClassicUIBuildTabNamesEnum,
  ClassicUIBuildTypeTabNamesEnum,
  ClassicUIProjectTabNamesEnum,
  stringifyId,
} from '../types'
import {internalProps} from '../types/BS_types'
import {emptyArray} from '../utils/empty'

import useInterval from './useInterval'

import {useAppSelector} from 'src/hooks/react-redux'
import {getTabParamsKey} from 'src/utils/tabs'

export type TabsList = {
  classicTabs: Array<Tab>
  sakuraTabs: Array<Tab>
}

export type TabProps = {
  allTabsReady: boolean
  tabs: TabsList
  refetchTabs: () => void
}

const implementedSakuraUITabs = {
  project: [
    ClassicUIProjectTabNamesEnum.projectOverview,
    ClassicUIProjectTabNamesEnum.investigations,
    ClassicUIProjectTabNamesEnum.projectChangeLog,
    ClassicUIProjectTabNamesEnum.problems,
  ].filter(Boolean),
  bt: [
    ClassicUIBuildTypeTabNamesEnum.buildTypeStatusDiv,
    ClassicUIBuildTypeTabNamesEnum.buildTypeHistoryList,
    ClassicUIBuildTypeTabNamesEnum.buildTypeBranches,
    ClassicUIBuildTypeTabNamesEnum.pendingChangesDiv,
    ClassicUIBuildTypeTabNamesEnum.buildTypeChains,
    ClassicUIBuildTypeTabNamesEnum.buildTypeChangeLog,
  ].filter(Boolean),
  build: [
    ClassicUIBuildTabNamesEnum.queuedBuildOverviewTab,
    ClassicUIBuildTabNamesEnum.buildResultsDiv,
    ClassicUIBuildTabNamesEnum.testsInfo,
    ClassicUIBuildTabNamesEnum.buildChangesDiv,
    ClassicUIBuildTabNamesEnum.buildLog,
    ClassicUIBuildTabNamesEnum.dependencies,
    ClassicUIBuildTabNamesEnum.artifacts,
  ],
  job: [
    ClassicUIBuildTabNamesEnum.buildChangesDiv,
    ClassicUIBuildTabNamesEnum.buildLog,
    ClassicUIBuildTabNamesEnum.artifacts,
  ],
}
const INTERVAL = 6000 // ms

const defaultResponse: TabsList = {
  classicTabs: emptyArray as Array<Tab>,
  sakuraTabs: emptyArray as Array<Tab>,
}

const useTabsEntityHelper = ({
  buildTypeId,
  buildId,
  pipelineId,
  tabParamsKey,
}: {
  projectId?: ProjectId | null | undefined
  buildTypeId?: BuildTypeId | null | undefined
  pipelineId?: PipelineId | null | undefined
  buildId?: BuildId | null | undefined
  tabParamsKey: string
}) => {
  let nodeType: NodeType | null | undefined = null

  if (pipelineId) {
    nodeType = 'job'
  } else if (buildId) {
    nodeType = 'build'
  } else if (buildTypeId) {
    nodeType = 'bt'
  } else {
    nodeType = 'project'
  }

  const resolvedBuildTypeId = useAppSelector(
    state => buildTypeId ?? getBuild(state, buildId)?.buildType,
  )
  const {availableTabs, allTabsReady, refetch} = restApi.endpoints.getTabs.useQuery(
    getTabsArg(tabParamsKey, nodeType !== 'build' && nodeType !== 'job'),
    {
      selectFromResult: ({data}) => ({
        allTabsReady: data != null,
        availableTabs: data ?? emptyArray,
      }),
    },
  )
  const isRunningBuild = useAppSelector(state => getBuild(state, buildId)?.state === 'running')

  return {
    nodeType,
    fetchTabsHandler: refetch,
    resolvedBuildTypeId,
    isRunningBuild,
    availableTabs,
    allTabsReady,
  }
}

export function useTabs(params: TabParams): TabProps {
  const tabParamsKey = getTabParamsKey(params)

  const {buildId, buildTypeId, projectId, pipelineId, runId, jobId, batchId} = params
  const {
    nodeType,
    resolvedBuildTypeId,
    fetchTabsHandler,
    isRunningBuild,
    availableTabs,
    allTabsReady,
  } = useTabsEntityHelper({
    buildId,
    buildTypeId,
    pipelineId,
    tabParamsKey,
  })

  useInterval(
    fetchTabsHandler,
    isRunningBuild && window.GLOBAL_FETCH_DISABLED !== true ? INTERVAL : null,
  )

  const tabs = React.useMemo(() => {
    if (!allTabsReady) {
      return defaultResponse
    }

    const implementedBuiltInTabs = implementedSakuraUITabs[nodeType] ?? emptyArray
    const result = availableTabs.reduce(
      (accumulator: TabsList, tab) => {
        let tabId = stringifyId(tab.id)

        switch (nodeType) {
          case 'job':
            const jobTab = JobTabs[stringifyId(tab.id)]
            if (!jobTab) {
              return accumulator
            } else {
              tabId = stringifyId(tab.id)
            }
            break
          case 'build':
            tabId = BuildTabs[stringifyId(tab.id)] ?? stringifyId(tab.id)
            break
          case 'bt':
            tabId = BuildTypeTabs[stringifyId(tab.id)] ?? stringifyId(tab.id)
            if (BuildTypeTabsWithoutAliases[tab.id]) {
              return accumulator
            }
            break
          default:
            tabId = ProjectTabs[stringifyId(tab.id)] ?? stringifyId(tab.id)
            if (
              internalProps['teamcity.ui.sakuraProblemsTab'] &&
              ProjectTabsWithoutAliases[tab.id]
            ) {
              return accumulator
            }
        }

        const isTabImplementedInSakuraUI = implementedBuiltInTabs.includes(tab.id) || tab.sakura

        const tabHref = getTabUrl(
          {
            projectId,
            buildTypeId: resolvedBuildTypeId,
            buildId,
            pipelineId,
            runId,
            jobId,
            batchId,
          },
          tabId,
        )

        const entity = {
          ...tab,
          id: tabId,
          href: tabHref,
        }

        if (!isTabImplementedInSakuraUI) {
          accumulator.classicTabs.push(entity)
        } else {
          accumulator.sakuraTabs.push(entity)
        }

        return accumulator
      },
      {classicTabs: [], sakuraTabs: []},
    )
    if (nodeType === 'job') {
      const tabKeys = Object.keys(JobTabs)
      result.sakuraTabs.sort((tab1, tab2) => tabKeys.indexOf(tab1.id) - tabKeys.indexOf(tab2.id))
    }
    result.sakuraTabs.sort((tab1, tab2) => (tab1.sakura ? 1 : 0) - (tab2.sakura ? 1 : 0))
    return result.classicTabs.length + result.sakuraTabs.length > 0 ? result : defaultResponse
  }, [
    allTabsReady,
    nodeType,
    availableTabs,
    projectId,
    resolvedBuildTypeId,
    buildId,
    pipelineId,
    runId,
    jobId,
    batchId,
  ])

  return {
    allTabsReady,
    tabs,
    refetchTabs: fetchTabsHandler,
  }
}
