import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import classNames from 'classnames'
import {memo} from 'react'
import type {EntryPointProps} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useAppSelector} from '../../../../../hooks/react-redux'
import {useHeightResizeObserver} from '../../../../../hooks/useResizeObserver'
import {getBuild, getPipelineIdFromBuildId} from '../../../../../selectors'
import type {BuildProblemsPreviewQuery} from '../../../../packages/BuildProblems/BuildProblemsPreview/__generated__/BuildProblemsPreviewQuery.graphql'
import BuildProblemsPreview from '../../../../packages/BuildProblems/BuildProblemsPreview/BuildProblemsPreview'
import type {TestsPreviewPanelCountsQuery} from '../../../../packages/Tests/TestsPreviewPanel/__generated__/TestsPreviewPanelCountsQuery.graphql'
import TestsPreviewPanel from '../../../../packages/Tests/TestsPreviewPanel/TestsPreviewPanel'
import BuildCanceled from '../../../BuildCanceled/BuildCanceled.container'
import BuildInfoTable from '../../../BuildInfoTable/BuildInfoTable'
import type {SnapshotDependenciesCountersQuery} from '../../../BuildInfoTable/SnapshotDependenciesCounters/__generated__/SnapshotDependenciesCountersQuery.graphql'
import PersonalBuild from '../../../BuildPersonal/BuildPersonal.container'
import BuildPinInfo from '../../../BuildPinInfo/BuildPinInfo.container'
import CustomizedBuildNote from '../../../CustomizedBuildNote/CustomizedBuildNote.lazy'
import Plugin from '../../../Plugin/Plugin'
import SequenceLoader from '../../../SequenceLoader/SequenceLoader'
import {useSequenceLoaderReadyHandler} from '../../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../SequenceLoader/SequenceLoader.types'
import styles from '../BuildDetails.module.css'
import BuildDetailsTabs from '../BuildDetailsTabs/BuildDetailsTabs'

import type {BuildDetailsContentProps} from './BuildDetailsContent.types'

type LoaderPlaceholderProps = SeqProps & {}
function LoaderPlaceholder(_: LoaderPlaceholderProps) {
  useSequenceLoaderReadyHandler(true)
  return (
    <div className={styles.loaderPlaceholder}>
      <LoaderInline>{'Loading...'}</LoaderInline>
    </div>
  )
}

type Props = BuildDetailsContentProps & {
  testCountsQuery: PreloadedQuery<TestsPreviewPanelCountsQuery>
  buildProblemsPreviewQuery: PreloadedQuery<BuildProblemsPreviewQuery>
  snapshotDependenciesCountersQuery: PreloadedQuery<SnapshotDependenciesCountersQuery>
}
function DetailsContentComponent(props: Props) {
  const {
    buildId,
    queued,
    testCountsQuery,
    snapshotDependenciesCountersQuery,
    buildProblemsPreviewQuery,
  } = props
  const [innerHeight, measureRef] = useHeightResizeObserver()
  const isPipeline = useAppSelector(state => getPipelineIdFromBuildId(state, buildId))
  const isPipelineRun = useAppSelector(state => getBuild(state, buildId)?.pipelineRun != null)

  return (
    <div style={{height: innerHeight}} className={styles.outerContainer}>
      <div ref={measureRef} className={styles.innerContainer}>
        <div className={styles.separator} />
        {!isPipelineRun && (
          <SequenceLoader className={styles.tabs} loader={<span>{'Loading tabs...'}</span>}>
            <BuildDetailsTabs seqKey="BuildDetailsTabs" />
          </SequenceLoader>
        )}
        <div className={classNames(styles.content, {[styles.runContent]: isPipelineRun})}>
          {!isPipeline && <CustomizedBuildNote withIcon className={styles.customizedBuildNote} />}
          <BuildInfoTable
            detailed
            buildId={buildId}
            snapshotDependenciesCountersQuery={snapshotDependenciesCountersQuery}
          />
          <div className={styles.secondInfoGroup}>
            <PersonalBuild className={styles.row} buildId={buildId} withIcon />
            <BuildCanceled className={styles.row} buildId={buildId} withIcon />
            <BuildPinInfo className={styles.row} buildId={buildId} withIcon />
          </div>
          <Plugin placeId={PlaceId.SAKURA_BUILD_LINE_EXPANDED} buildId={buildId} />
          <SequenceLoader
            loader={
              <div className={styles.loader}>
                <LoaderInline>{'Loading...'}</LoaderInline>
              </div>
            }
          >
            {!queued ? (
              <BuildProblemsPreview
                buildId={buildId}
                seqKey="BuildProblemsPreview"
                buildProblemsPreviewQueryRef={buildProblemsPreviewQuery}
              />
            ) : null}
            {!queued ? (
              <TestsPreviewPanel
                buildId={buildId}
                seqKey="TestList"
                countsQuery={testCountsQuery}
              />
            ) : null}
            <LoaderPlaceholder seqKey="loaderPlaceholder" />
          </SequenceLoader>
        </div>
      </div>
    </div>
  )
}

type Queries = {
  testCounts: TestsPreviewPanelCountsQuery
  snapshotDependenciesCounters: SnapshotDependenciesCountersQuery
  buildProblemsPreviewQuery: BuildProblemsPreviewQuery
}
const DetailsContent = memo(function DetailsContent({
  queries,
  props,
}: EntryPointProps<Queries, {}, BuildDetailsContentProps, {}>) {
  return (
    <DetailsContentComponent
      {...props}
      testCountsQuery={queries.testCounts}
      snapshotDependenciesCountersQuery={queries.snapshotDependenciesCounters}
      buildProblemsPreviewQuery={queries.buildProblemsPreviewQuery}
    />
  )
})
export default DetailsContent
export type DetailsContentType = typeof DetailsContent
