import {Anchor} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import DropdownMenu from '@jetbrains/ring-ui-built/components/dropdown-menu/dropdown-menu'
import {Type} from '@jetbrains/ring-ui-built/components/list/consts'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import type {ReactNode} from 'react'
import * as React from 'react'
import {useEffect, useRef, useState} from 'react'

import {useBuildId} from '../../../../../hooks/routes'
import {useTabs} from '../../../../../hooks/useTabs'
import {
  getBuild,
  getPipelineBatchIdFromBuildId,
  getPipelineIdFromBuildId,
  getPipelineJobIdFromBuildId,
  getPipelineRunIdFromBuildId,
} from '../../../../../selectors'
import type {Tab} from '../../../../../types'
import {ClassicUIBuildTabNamesEnum, stringifyId} from '../../../../../types'
import {parseTabTitle} from '../../../../../utils/tabs'
import RouterLink from '../../../RouterLink/RouterLink'
import {useSequenceLoaderReadyHandler} from '../../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../SequenceLoader/SequenceLoader.types'
import {BuildTabs} from '../../../ToggleSakuraUI/ToggleSakuraUI.utils'

import styles from './BuildDetailsTabs.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const HEIGHT = 16

type Props = SeqProps & {}

function BuildDetailsTabs() {
  const buildId = useBuildId()
  const pipelineId = useAppSelector(state => getPipelineIdFromBuildId(state, buildId))
  const runId = useAppSelector(state => getPipelineRunIdFromBuildId(state, buildId))
  const jobId = useAppSelector(state => getPipelineJobIdFromBuildId(state, buildId))
  const batchId = useAppSelector(state => getPipelineBatchIdFromBuildId(state, buildId))

  const {
    tabs: {sakuraTabs, classicTabs},
    allTabsReady,
  } = useTabs({
    buildId,
    pipelineId,
    runId,
    jobId,
    batchId,
  })

  const tabs = React.useMemo(() => [...sakuraTabs, ...classicTabs], [classicTabs, sakuraTabs])
  useSequenceLoaderReadyHandler(allTabsReady)
  const isQueued = useAppSelector(state => getBuild(state, buildId)?.state === 'queued')

  const [firstInvisibleIndex, setFirstInvisibleIndex] = useState(0)
  const container = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const containerEl = container.current
    if (containerEl != null) {
      const observer = new ResizeObserver(() => {
        const {top} = containerEl.getBoundingClientRect()
        setFirstInvisibleIndex(
          [...containerEl.querySelectorAll('[data-build-details-tab]')].findIndex(
            el => el.getBoundingClientRect().top - top >= HEIGHT,
          ),
        )
      })
      observer.observe(containerEl)
      return () => observer.disconnect()
    }
    return undefined
  }, [])

  function renderTab(tab: Tab, more?: ReactNode) {
    const tabId = BuildTabs[stringifyId(tab.id)] || stringifyId(tab.id)
    const {name, counter} = parseTabTitle(tab.title)
    return (
      <div data-build-details-tab className={styles.tab} key={stringifyId(tabId)}>
        {tab.href != null && (
          <div className={styles.link}>
            <RouterLink to={tab.href} title={name}>
              {name}
            </RouterLink>
          </div>
        )}
        {counter != null && <span className={styles.counter}>{counter}</span>}
        {name === 'Build Log' && !isQueued ? (
          <IconButton
            className={styles.icon}
            href={resolveRelative('/app/buildLog', {
              buildId: stringifyId(buildId),
              indent: 'true',
            })}
            icon="download"
            title="Download build log"
          />
        ) : null}
        {more}
      </div>
    )
  }

  return (
    <div className={styles.tabs} ref={container}>
      {tabs
        .filter(
          tab =>
            tab.id !== ClassicUIBuildTabNamesEnum.buildResultsDiv &&
            tab.id !== ClassicUIBuildTabNamesEnum.queuedBuildOverviewTab,
        )
        .map((tab, i) =>
          renderTab(
            tab,
            i === firstInvisibleIndex - 1 && (
              <DropdownMenu
                className={styles.more}
                anchor={<Anchor className={styles.moreAnchor}>{'More'}</Anchor>}
                data={tabs.slice(i + 1).map(otherTab => ({
                  rgItemType: Type.CUSTOM,
                  template: renderTab(otherTab),
                  key: otherTab.id,
                }))}
              />
            ),
          ),
        )}
    </div>
  )
}

export default React.memo<Props>(BuildDetailsTabs)
