import {connect} from 'react-redux'

import type {State} from '../../../reducers/types'
import {getBuildCanceledInfo, getBuild} from '../../../selectors'

import BuildCanceled from './BuildCanceled'
import type {OwnProps, StateProps} from './BuildCanceled.types'

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const {buildType: buildTypeId} = getBuild(state, props.buildId) || {}
  const canceledInfo = getBuildCanceledInfo(state, props.buildId)
  const {text, user} = canceledInfo || {}
  return {
    user,
    canceled: canceledInfo != null,
    text,
    buildTypeId,
  }
}

export default connect(mapStateToProps, {})(BuildCanceled)
